import{_ as o,c as t,b as n,a2 as a}from"./chunks/framework.BEqfOpL-.js";const s="/images/megaphone_invite_1_users.webp",r="/images/megaphone_invite_2_form.webp",i="/images/megaphone_invite_3_role.webp",h="/images/megaphone_invite_4_network.webp",d="/images/megaphone_invite_5_filled.webp",p="/images/megaphone_invite_6_done.webp",_=JSON.parse('{"title":"Connect Megaphone","description":"If your podcast is hosted on Megaphone, you can bring its downloads into PodSEO. Megaphone has no sign-in or API token you can hand to another app, so the connection works by invitation: you invite PodSEO to your Megaphone organization as a read-only user, and PodSEO reads the downloads of the show you connected. Once connected, your Megaphone downloads appear in Analytics next to your other sources, and refresh daily.","frontmatter":{},"headers":[],"relativePath":"features/megaphone-connection.md","filePath":"features/megaphone-connection.md"}'),l={name:"features/megaphone-connection.md"};function c(g,e,u,m,w,f){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="connect-megaphone" tabindex="-1">Connect Megaphone <a class="header-anchor" href="#connect-megaphone" aria-label="Permalink to &quot;Connect Megaphone&quot;">​</a></h1><p>If your podcast is hosted on <strong>Megaphone</strong>, you can bring its downloads into PodSEO. Megaphone has no sign-in or API token you can hand to another app, so the connection works by invitation: you invite PodSEO to your Megaphone organization as a read-only user, and PodSEO reads the downloads of the show you connected. Once connected, your Megaphone downloads appear in <strong>Analytics</strong> next to your other sources, and refresh daily.</p><p>The connection is free on every plan. In an organization, only <strong>Admins</strong> and <strong>Owners</strong> can connect a source in PodSEO; other team members can view the numbers.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>You need admin rights in Megaphone.</strong> Only an <strong>Organization Admin</strong> or a <strong>Network Admin</strong> can invite users. If you don&#39;t have that role, ask the person who manages your Megaphone organization to send the invite with the details PodSEO gives you.</li><li><strong>Know which network holds your show.</strong> In Megaphone, every show belongs to a network. You&#39;ll give PodSEO access to that network.</li><li><strong>Keep PodSEO open in another tab.</strong> You&#39;ll copy three values from PodSEO into Megaphone&#39;s invite form.</li></ul><h2 id="step-1-get-your-code-in-podseo" tabindex="-1">Step 1: Get your code in PodSEO <a class="header-anchor" href="#step-1-get-your-code-in-podseo" aria-label="Permalink to &quot;Step 1: Get your code in PodSEO&quot;">​</a></h2><ol><li>Choose your podcast, open <strong>Analytics</strong> and select the <strong>Megaphone</strong> tab.</li><li>Click <strong>Connect Megaphone</strong>.</li></ol><p>PodSEO shows a 6-character code, with the first name and email address to use in the invite. Each value has a <strong>Copy</strong> button. The code tells PodSEO which show and which PodSEO account the invite is for, so type it exactly as shown.</p><p>The code can be used once and is valid for <strong>30 days</strong>. If it expires before PodSEO receives an invite, the page shows <strong>Get a new code</strong>: click it and use the new code instead.</p><h2 id="step-2-open-the-users-page-in-megaphone" tabindex="-1">Step 2: Open the users page in Megaphone <a class="header-anchor" href="#step-2-open-the-users-page-in-megaphone" aria-label="Permalink to &quot;Step 2: Open the users page in Megaphone&quot;">​</a></h2><p>Sign in to Megaphone with an Organization Admin or Network Admin account, open <strong>Users</strong> (from <strong>Settings</strong>, or directly from the left menu) and click <strong>Invite User</strong>.</p><p><a href="/images/megaphone_invite_1_users.webp" title="Open screenshot at full size"><img src="'+s+'" alt="Megaphone Users page with the Invite User button"></a></p><p>The <strong>Invite User</strong> form opens, with empty user details.</p><p><a href="/images/megaphone_invite_2_form.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Megaphone&#39;s empty Invite User form"></a></p><h2 id="step-3-fill-in-the-name-and-email" tabindex="-1">Step 3: Fill in the name and email <a class="header-anchor" href="#step-3-fill-in-the-name-and-email" aria-label="Permalink to &quot;Step 3: Fill in the name and email&quot;">​</a></h2><p>Copy each value from PodSEO:</p><table tabindex="0"><thead><tr><th>Megaphone field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>First name</strong></td><td><code>PodSEO</code></td></tr><tr><td><strong>Last name</strong></td><td>Your 6-character code from PodSEO (for example <code>K7X2Q9</code>)</td></tr><tr><td><strong>Email address</strong></td><td><code>megaphone@podseo.com</code></td></tr></tbody></table><p>The code goes in <strong>Last name</strong>, not in the email address. PodSEO matches the invite to your request through it.</p><h2 id="step-4-choose-network-partner-and-the-network" tabindex="-1">Step 4: Choose Network Partner and the network <a class="header-anchor" href="#step-4-choose-network-partner-and-the-network" aria-label="Permalink to &quot;Step 4: Choose Network Partner and the network&quot;">​</a></h2><ol><li>In <strong>Role</strong>, choose <strong>Network Partner</strong>. Megaphone describes it as <strong>View network metrics</strong>: it can read reports and cannot change anything.</li></ol><p><a href="/images/megaphone_invite_3_role.webp" title="Open screenshot at full size"><img src="'+i+'" alt="Choosing the Network Partner role in Megaphone"></a></p><ol start="2"><li>Click <strong>Assign Networks</strong>, tick the network that holds your show and click <strong>Save</strong>.</li></ol><p><a href="/images/megaphone_invite_4_network.webp" title="Open screenshot at full size"><img src="'+h+'" alt="Selecting the network that holds the show in Megaphone"></a></p><ol start="3"><li>Check the form: first name, last name (your code), email, role <strong>Network Partner</strong> and the network you assigned. Then click <strong>Invite</strong>.</li></ol><p><a href="/images/megaphone_invite_5_filled.webp" title="Open screenshot at full size"><img src="'+d+'" alt="Completed Megaphone invite with the PodSEO code as Last name"></a></p><p>PodSEO now appears in your Megaphone users list with the role <strong>Network Partner</strong>. Its name in the list can differ from the one you typed.</p><p><a href="/images/megaphone_invite_6_done.webp" title="Open screenshot at full size"><img src="'+p+'" alt="Megaphone users list with megaphone@podseo.com as Network Partner"></a></p><h2 id="step-5-tell-podseo-you-sent-the-invite" tabindex="-1">Step 5: Tell PodSEO you sent the invite <a class="header-anchor" href="#step-5-tell-podseo-you-sent-the-invite" aria-label="Permalink to &quot;Step 5: Tell PodSEO you sent the invite&quot;">​</a></h2><p>Back in PodSEO, click <strong>I&#39;ve sent the invite</strong>. You can leave the page: PodSEO checks for new invitations every 10 minutes.</p><p>When the invite arrives, PodSEO confirms that the show you connected is in the network you shared. The status changes to <strong>Confirming your Megaphone connection</strong>; if a person needs to confirm it, our team does and emails you. Your downloads appear after the first import, then update daily. See <a href="/features/hosting-analytics.html">Hosting platform reports</a> to read them.</p><h2 id="what-podseo-can-see" tabindex="-1">What PodSEO can see <a class="header-anchor" href="#what-podseo-can-see" aria-label="Permalink to &quot;What PodSEO can see&quot;">​</a></h2><p>A <strong>Network Partner</strong> in Megaphone can see the reports of every show in the networks you assigned. PodSEO reads <strong>only the shows that PodSEO users connect</strong>, and only their download statistics. It never publishes, edits or deletes anything in Megaphone: the role doesn&#39;t allow it, and PodSEO doesn&#39;t try.</p><p>If your network holds several shows and you want to connect another one, start from that show&#39;s <strong>Megaphone</strong> tab in PodSEO.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>The Megaphone tab is missing.</strong> Check that you selected the right podcast. The tab appears for shows whose feed PodSEO recognises as hosted on Megaphone.</p><p><strong>My code expired.</strong> Codes last 30 days and work once. Click <strong>Get a new code</strong> and send a new invite with it as the Last name.</p><p><strong>I invited the wrong network or typed the code wrong.</strong> Remove <code>megaphone@podseo.com</code> from your Megaphone users, then send a new invite with the correct details. If your code has been used or has expired, get a new one first.</p><p><strong>PodSEO says Megaphone no longer accepts the connection.</strong> This happens when <code>megaphone@podseo.com</code> was removed from your Megaphone users, or the show left your Megaphone organization. Click <strong>Invite PodSEO again</strong> and follow the steps with the new code. Numbers already shown keep their original dates.</p><p><strong>The invite was sent days ago and nothing changed.</strong> <a href="https://podseo.com/contact/" target="_blank" rel="noreferrer">Contact support</a> with the show&#39;s name and your Megaphone network&#39;s name. Never send your Megaphone password.</p><h2 id="how-to-disconnect" tabindex="-1">How to disconnect <a class="header-anchor" href="#how-to-disconnect" aria-label="Permalink to &quot;How to disconnect&quot;">​</a></h2><ol><li>In PodSEO, open <strong>Settings → Connections</strong>, expand <strong>Megaphone</strong> for the correct show and choose <strong>Disconnect…</strong>. PodSEO stops reading your downloads. Your Megaphone numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect.</li><li>In Megaphone, open <strong>Users</strong> and remove <code>megaphone@podseo.com</code>. This ends PodSEO&#39;s access to your organization.</li></ol><p>If PodSEO reads several shows in the same network for you, removing <code>megaphone@podseo.com</code> in Megaphone stops all of them.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="/features/analytics-connections.html">Connect your analytics</a>: every source you can connect, and how to manage them</li><li><a href="/features/hosting-analytics.html">Hosting platform reports</a>: read your host&#39;s downloads, episodes and audience</li><li><a href="/features/analytics.html">Reading Analytics</a>: compare Megaphone downloads with Apple, Spotify and YouTube</li></ul>',44)])])}const b=o(l,[["render",c]]);export{_ as __pageData,b as default};
